import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void cross_entropy_kernel(
    const half* predictions,
    const int* targets,
    half* output,
    int batch_size,
    int num_classes
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= batch_size) return;

    // Get the target class for this sample
    int target_class = targets[idx];

    // Find max value for numerical stability
    half max_val = predictions[idx * num_classes + 0];
    for (int i = 1; i < num_classes; i++) {
        max_val = fmaxf(__half2float(max_val), __half2float(predictions[idx * num_classes + i]));
    }

    // Compute sum of exponentials
    float sum_exp = 0.0f;
    for (int i = 0; i < num_classes; i++) {
        float exp_val = expf(__half2float(predictions[idx * num_classes + i]) - __half2float(max_val));
        sum_exp += exp_val;
    }

    // Compute log(sum_exp)
    float log_sum_exp = logf(sum_exp);

    // Compute negative log probability of target class
    float target_log_prob = __half2float(predictions[idx * num_classes + target_class]) - __half2float(max_val) - log_sum_exp;

    // Store result
    output[idx] = __float2half(-target_log_prob);
}

// Wrapper function to launch kernel
extern "C" void launch_cross_entropy(
    const half* predictions,
    const int* targets,
    half* output,
    int batch_size,
    int num_classes
) {
    const int block_size = 256;
    const int grid_size = (batch_size + block_size - 1) / block_size;

    cross_entropy_kernel<<<grid_size, block_size>>>(
        predictions, targets, output, batch_size, num_classes
    );

    cudaDeviceSynchronize();
}
"""

# Load the CUDA extension
module = load_inline(
    name="cross_entropy_ext",
    cpp_sources="",
    cuda_sources=cuda_source,
    functions=["launch_cross_entropy"],
    verbose=True
)

class ModelNew(torch.nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, predictions, targets):
        # Ensure inputs are float16 and contiguous
        predictions = predictions.to(torch.float16)
        targets = targets.to(torch.int32)

        # Create output tensor
        output = torch.empty(predictions.size(0), dtype=torch.float16, device=predictions.device)

        # Launch CUDA kernel
        module.launch_cross_entropy(
            predictions.data_ptr(),
            targets.data_ptr(),
            output.data_ptr(),
            predictions.size(0),
            predictions.size(1)
        )

        return output

# Test the implementation
if __name__ == "__main__":
    batch_size = 32768
    num_classes = 4096
    input_shape = (num_classes,)

    # Create test inputs
    predictions = torch.rand(batch_size, *input_shape, dtype=torch.float16)
    targets = torch.randint(0, num_classes, (batch_size,), dtype=torch.int32)

    # Test both implementations
    model_ref = torch.nn.CrossEntropyLoss()
    model_new = ModelNew()

    # Reference implementation
    ref_output = model_ref(predictions, targets)

    # New implementation
    new_output = model_new(predictions, targets)

    print(f"Reference output shape: {ref_output.shape}")
    print(f"New output shape: {new_output.shape}")
    print(f"Max difference: {torch.max(torch.abs(ref_output - new_output)).item()}")
